<?php
/**
 * PiPusher device API.
 *
 * Devices authenticate with the header  X-Device-Auth: <uuid>:<secret>
 * The uuid/secret pair is generated by the device on first start; the server stores a hash of
 * the secret the first time it sees the uuid (trust on first use) and requires it afterwards.
 *
 *   POST api.php?action=sync   JSON {name, hostname, client_version, config_version, registration_key, info}
 *        -> {status: pending|nolayout|ready, code, name, poll_interval, screenshot_interval, commands[], muted, version, config?}
 *   GET  api.php?action=file&media=<id>&path=<relative path>   -> raw file (approved devices only)
 *   POST api.php?action=screenshot   body: image/jpeg            -> stores the screen's latest screenshot
 *   GET  api.php?action=client&os=<goos>&arch=<goarch>&go=<go version>
 *        -> this server's client package for the device (header X-PiPusher-Version), for the "update" command
 */
declare(strict_types=1);
require __DIR__ . '/inc/bootstrap.php';

function device_from_auth(): array
{
    $auth = $_SERVER['HTTP_X_DEVICE_AUTH'] ?? '';
    if (!preg_match('/^([A-Za-z0-9-]{8,64}):([A-Za-z0-9]{16,128})$/', $auth, $m)) {
        json_out(['error' => 'missing or malformed X-Device-Auth header'], 401);
    }
    return [$m[1], $m[2]];
}

$action = $_GET['action'] ?? '';

if ($action === 'sync') {
    if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
        json_out(['error' => 'POST required'], 405);
    }
    [$uuid, $secret] = device_from_auth();
    $body = json_decode((string)file_get_contents('php://input'), true);
    if (!is_array($body)) {
        $body = [];
    }
    $regKey = (string)setting('registration_key', '');
    $keyOk = $regKey !== '' && hash_equals($regKey, (string)($body['registration_key'] ?? ''));
    $info = is_array($body['info'] ?? null) ? $body['info'] : [];
    $info['client_version'] = (string)($body['client_version'] ?? '');
    $info['hostname'] = (string)($body['hostname'] ?? '');

    $device = q1('SELECT * FROM devices WHERE uuid = ?', [$uuid]);
    if (!$device) {
        $name = trim((string)($body['name'] ?? '')) ?: (trim($info['hostname']) ?: 'Pi ' . substr($uuid, 0, 6));
        [$defLayout, $defPlaylist, $defGroup] = new_screen_defaults();
        x('INSERT INTO devices (uuid, secret_hash, code, name, status, layout_id, playlist_id, group_id, use_group_content, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
            [$uuid, hash('sha256', $secret), random_code(), mb_substr($name, 0, 80), $keyOk ? 'approved' : 'pending',
             $defLayout, $defPlaylist, $defGroup, $defGroup ? 1 : 0, now()]);
        $device = q1('SELECT * FROM devices WHERE id = ?', [last_id()]);
    } elseif (!hash_equals($device['secret_hash'], hash('sha256', $secret))) {
        json_out(['error' => 'device credentials do not match'], 403);
    } elseif ($device['status'] === 'pending' && $keyOk) {
        x("UPDATE devices SET status = 'approved' WHERE id = ?", [$device['id']]);
        $device['status'] = 'approved';
    }

    x('UPDATE devices SET last_seen = ?, ip = ?, info = ?, command = NULL WHERE id = ?',
        [now(), $_SERVER['REMOTE_ADDR'] ?? '', json_encode($info, JSON_UNESCAPED_SLASHES), $device['id']]);

    $resp = [
        'status' => 'pending',
        'code' => $device['code'],
        'name' => $device['name'],
        'poll_interval' => poll_interval(),
        'screenshot_interval' => screenshot_interval(),
        'commands' => array_values(array_filter(explode(',', (string)$device['command']))),
        'muted' => (bool)$device['muted'],
        'server_time' => now(),
    ];
    if ($device['status'] === 'approved') {
        $payload = screen_payload($device);
        if ($payload === null) {
            $resp['status'] = 'nolayout';
        } else {
            $resp['status'] = 'ready';
            $resp['version'] = payload_version($payload);
            if (($body['config_version'] ?? '') !== $resp['version']) {
                $resp['config'] = $payload;
            }
        }
    }
    json_out($resp);
}

if ($action === 'file') {
    [$uuid, $secret] = device_from_auth();
    $device = q1('SELECT * FROM devices WHERE uuid = ?', [$uuid]);
    if (!$device || !hash_equals($device['secret_hash'], hash('sha256', $secret)) || $device['status'] !== 'approved') {
        json_out(['error' => 'not authorised'], 403);
    }
    $mediaId = (int)($_GET['media'] ?? 0);
    $path = safe_rel_path((string)($_GET['path'] ?? ''));
    $row = $path === null ? null : q1('SELECT * FROM media_files WHERE media_id = ? AND path = ?', [$mediaId, $path]);
    $abs = $row ? media_dir($mediaId) . '/' . $path : null;
    if (!$abs || !is_file($abs)) {
        json_out(['error' => 'not found'], 404);
    }
    send_file($abs);
}

if ($action === 'client') {
    [$uuid, $secret] = device_from_auth();
    $device = q1('SELECT * FROM devices WHERE uuid = ?', [$uuid]);
    if (!$device || !hash_equals($device['secret_hash'], hash('sha256', $secret)) || $device['status'] !== 'approved') {
        json_out(['error' => 'not authorised'], 403);
    }
    $file = client_package_for((string)($_GET['os'] ?? ''), (string)($_GET['arch'] ?? ''), (string)($_GET['go'] ?? ''));
    $d = client_downloads()[$file] ?? null;
    if (!$d || empty($d['path'])) {
        json_out(['error' => 'this server has no client package for ' . ($_GET['os'] ?? '') . '/' . ($_GET['arch'] ?? '')], 404);
    }
    header('X-PiPusher-Version: ' . PP_VERSION);
    send_file($d['path']);
}

if ($action === 'screenshot') {
    [$uuid, $secret] = device_from_auth();
    $device = q1('SELECT * FROM devices WHERE uuid = ?', [$uuid]);
    if (!$device || !hash_equals($device['secret_hash'], hash('sha256', $secret))) {
        json_out(['error' => 'not authorised'], 403);
    }
    $img = (string)file_get_contents('php://input', false, null, 0, 5 * 1024 * 1024 + 1);
    if (strlen($img) > 5 * 1024 * 1024 || !str_starts_with($img, "\xFF\xD8\xFF")) {
        json_out(['error' => 'expected a JPEG of at most 5 MB'], 400);
    }
    ensure_data_dirs();
    $dest = screenshot_path((int)$device['id']);
    file_put_contents($dest . '.tmp', $img);
    rename($dest . '.tmp', $dest);
    x('UPDATE devices SET screenshot_at = ? WHERE id = ?', [now(), $device['id']]);
    json_out(['ok' => true]);
}

json_out(['error' => 'unknown action', 'version' => PP_VERSION], 404);
